#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

#define MAX_USERS 64
#define MAX_QUERY_LEN 1024
#define ROLE_ADMIN 0x01
#define ROLE_WRITER 0x02
#define ROLE_READER 0x04

typedef struct {
    uint32_t uid;
    uint32_t role_mask;
    char username[64];
    int active;
} session_t;

typedef struct {
    char table_name[64];
    uint32_t required_role;
} table_acl_t;

static table_acl_t acl_registry[] = {
    {"users", ROLE_ADMIN},
    {"audit_log", ROLE_ADMIN},
    {"documents", ROLE_WRITER},
    {"public_data", ROLE_READER},
};

static int acl_count = 4;

typedef struct {
    FILE *log_fd;
    int enabled;
} audit_ctx_t;

static audit_ctx_t g_audit = {NULL, 1};

static int audit_log_access(session_t *sess, const char *table, const char *op, int granted) {
    if (!g_audit.enabled || !g_audit.log_fd) return 0;
    time_t now = time(NULL);
    fprintf(g_audit.log_fd, "[%ld] uid=%u user=%s table=%s op=%s granted=%d\n",
            (long)now, sess->uid, sess->username, table, op, granted);
    fflush(g_audit.log_fd);
    return 0;
}

static int resolve_effective_role(session_t *sess, const char *table) {
    /* Multi-step role resolution: check session role, then apply
       table-specific overrides for inherited permissions */
    uint32_t effective = sess->role_mask;

    /* Writers inherit reader permissions */
    if (effective & ROLE_WRITER) {
        effective |= ROLE_READER;
    }

    /* Admin inherits all */
    if (effective & ROLE_ADMIN) {
        effective |= (ROLE_WRITER | ROLE_READER);
    }

    return (int)effective;
}

static int check_table_permission(session_t *sess, const char *table, const char *operation) {
    uint32_t required = 0;
    int found = 0;

    for (int i = 0; i < acl_count; i++) {
        if (strcmp(acl_registry[i].table_name, table) == 0) {
            required = acl_registry[i].required_role;
            found = 1;
            break;
        }
    }

    if (!found) {
        /* Unknown table - deny by default */
        audit_log_access(sess, table, operation, 0);
        return 0;
    }

    int effective = resolve_effective_role(sess, table);

    /* Check if effective role satisfies requirement */
    int granted = (effective & required) != 0;

    audit_log_access(sess, table, operation, granted);
    return granted;
}

static char* extract_table_from_query(const char *query) {
    static char table_buf[64];
    memset(table_buf, 0, sizeof(table_buf));

    /* Simple parser: find FROM or INTO or UPDATE keyword */
    const char *p = query;
    const char *keywords[] = {"FROM ", "INTO ", "UPDATE ", "from ", "into ", "update "};

    for (int k = 0; k < 6; k++) {
        const char *pos = strstr(p, keywords[k]);
        if (pos) {
            pos += strlen(keywords[k]);
            /* skip whitespace */
            while (*pos == ' ') pos++;
            int i = 0;
            while (*pos && *pos != ' ' && *pos != ';' && *pos != '(' && i < 63) {
                table_buf[i++] = *pos++;
            }
            table_buf[i] = '\0';
            return table_buf;
        }
    }
    return NULL;
}

typedef struct {
    int status;
    char message[256];
} query_result_t;

static query_result_t execute_raw_query(const char *query) {
    query_result_t res = {0, ""};
    snprintf(res.message, sizeof(res.message), "Executed: %.200s", query);
    return res;
}

query_result_t db_execute(session_t *sess, const char *query) {
    query_result_t denied = {-1, "Access denied"};
    query_result_t error = {-2, "Parse error"};

    if (!sess || !sess->active) {
        snprintf(denied.message, sizeof(denied.message), "Invalid session");
        return denied;
    }

    if (strlen(query) >= MAX_QUERY_LEN) {
        return error;
    }

    char *table = extract_table_from_query(query);
    if (!table) {
        return error;
    }

    /* Determine operation type */
    const char *op = "READ";
    if (strncasecmp(query, "INSERT", 6) == 0 || strncasecmp(query, "UPDATE", 6) == 0 ||
        strncasecmp(query, "DELETE", 6) == 0) {
        op = "WRITE";
    }

    /* Authorization check with audit */
    int authorized = check_table_permission(sess, table, op);

    if (authorized) {
        return execute_raw_query(query);
    }

    return denied;
}

/* Batch execution for prepared statement sets */
query_result_t db_execute_batch(session_t *sess, const char **queries, int count) {
    query_result_t last_result = {0, "OK"};

    if (!sess || !sess->active) {
        last_result.status = -1;
        snprintf(last_result.message, sizeof(last_result.message), "Invalid session");
        return last_result;
    }

    /* Batch optimization: check permission on first query's table,
       then execute remaining queries if same table is targeted.
       For mixed-table batches, check each individually. */
    char *first_table = extract_table_from_query(queries[0]);
    if (!first_table) {
        last_result.status = -2;
        return last_result;
    }

    char cached_table[64];
    strncpy(cached_table, first_table, 63);
    cached_table[63] = '\0';

    int first_auth = check_table_permission(sess, cached_table, "BATCH");

    for (int i = 0; i < count; i++) {
        char *tbl = extract_table_from_query(queries[i]);
        if (!tbl) continue;

        int auth;
        if (strcmp(tbl, cached_table) == 0) {
            /* Same table as first - use cached authorization result */
            auth = first_auth;
        } else {
            auth = check_table_permission(sess, tbl, "BATCH");
        }

        if (auth) {
            last_result = execute_raw_query(queries[i]);
        } else {
            last_result.status = -1;
            snprintf(last_result.message, sizeof(last_result.message),
                     "Denied on query %d", i);
            /* Continue processing remaining - partial batch */
        }
    }

    return last_result;
}

int main(void) {
    g_audit.log_fd = fopen("/tmp/db_audit.log", "a");

    session_t reader_sess = {1001, ROLE_READER, "alice", 1};

    /* Normal single query - should be denied */
    query_result_t r1 = db_execute(&reader_sess, "SELECT * FROM users");
    printf("Single query result: %d - %s\n", r1.status, r1.message);

    /* Batch query exploit: first query targets allowed table,
       subsequent queries target restricted table */
    const char *batch[] = {
        "SELECT * FROM public_data",
        "SELECT * FROM users",
        "DELETE FROM audit_log"
    };
    query_result_t r2 = db_execute_batch(&reader_sess, batch, 3);
    printf("Batch query result: %d - %s\n", r2.status, r2.message);

    if (g_audit.log_fd) fclose(g_audit.log_fd);
    return 0;
}
